using Microsoft.EntityFrameworkCore;
using NeonTycoon.Domain;
namespace NeonTycoon.Infrastructure;
public sealed class GameDb(DbContextOptions<GameDb> options) : DbContext(options)
{
 public DbSet<Player> Players => Set<Player>(); public DbSet<PlayerResources> PlayerResources => Set<PlayerResources>(); public DbSet<BuildingDefinition> BuildingDefinitions => Set<BuildingDefinition>(); public DbSet<PlayerBuilding> PlayerBuildings => Set<PlayerBuilding>(); public DbSet<ResearchDefinition> ResearchDefinitions => Set<ResearchDefinition>(); public DbSet<PlayerResearch> PlayerResearch => Set<PlayerResearch>(); public DbSet<Mission> Missions => Set<Mission>(); public DbSet<PlayerMission> PlayerMissions => Set<PlayerMission>(); public DbSet<Achievement> Achievements => Set<Achievement>(); public DbSet<PlayerAchievement> PlayerAchievements => Set<PlayerAchievement>(); public DbSet<DailyReward> DailyRewards => Set<DailyReward>(); public DbSet<Referral> Referrals => Set<Referral>(); public DbSet<EconomyTransaction> EconomyTransactions => Set<EconomyTransaction>(); public DbSet<GameEvent> GameEvents => Set<GameEvent>();
 protected override void OnModelCreating(ModelBuilder m)
 {
  m.Entity<Player>().HasIndex(x=>x.TelegramId).IsUnique(); m.Entity<Player>().HasIndex(x=>x.ReferralCode).IsUnique(); m.Entity<Player>().HasIndex(x=>x.LifetimeCredits);
  m.Entity<PlayerResources>().HasKey(x=>x.PlayerId); m.Entity<Player>().HasOne(x=>x.Resources).WithOne().HasForeignKey<PlayerResources>(x=>x.PlayerId);
  m.Entity<Player>().HasMany(x=>x.Buildings).WithOne().HasForeignKey(x=>x.PlayerId);
  m.Entity<Player>().HasMany(x=>x.Technologies).WithOne().HasForeignKey(x=>x.PlayerId);
  m.Entity<Player>().HasMany(x=>x.Missions).WithOne().HasForeignKey(x=>x.PlayerId);
  m.Entity<Player>().HasMany(x=>x.Achievements).WithOne().HasForeignKey(x=>x.PlayerId);
  m.Entity<PlayerBuilding>().HasKey(x=>new {x.PlayerId,x.BuildingId}); m.Entity<PlayerBuilding>().HasOne<BuildingDefinition>().WithMany().HasForeignKey(x=>x.BuildingId);
  m.Entity<PlayerResearch>().HasKey(x=>new {x.PlayerId,x.ResearchId}); m.Entity<PlayerResearch>().HasOne<ResearchDefinition>().WithMany().HasForeignKey(x=>x.ResearchId);
  m.Entity<PlayerMission>().HasKey(x=>new {x.PlayerId,x.MissionId}); m.Entity<PlayerMission>().HasOne<Mission>().WithMany().HasForeignKey(x=>x.MissionId);
  m.Entity<PlayerAchievement>().HasKey(x=>new {x.PlayerId,x.AchievementId}); m.Entity<PlayerAchievement>().HasOne<Achievement>().WithMany().HasForeignKey(x=>x.AchievementId);
  m.Entity<BuildingDefinition>().HasKey(x=>x.Id); m.Entity<ResearchDefinition>().HasKey(x=>x.Id); m.Entity<Mission>().HasKey(x=>x.Id); m.Entity<Achievement>().HasKey(x=>x.Id);
  m.Entity<DailyReward>().HasIndex(x=>new {x.PlayerId,x.Day}).IsUnique(); m.Entity<DailyReward>().HasOne<Player>().WithMany().HasForeignKey(x=>x.PlayerId);
  m.Entity<Referral>().HasIndex(x=>x.ReferredId).IsUnique(); m.Entity<Referral>().HasOne<Player>().WithMany().HasForeignKey(x=>x.ReferrerId).OnDelete(DeleteBehavior.Restrict); m.Entity<Referral>().HasOne<Player>().WithMany().HasForeignKey(x=>x.ReferredId).OnDelete(DeleteBehavior.Restrict);
  m.Entity<EconomyTransaction>().HasIndex(x=>new {x.PlayerId,x.CreatedAt}); m.Entity<EconomyTransaction>().HasOne<Player>().WithMany().HasForeignKey(x=>x.PlayerId);
  foreach(var property in m.Model.GetEntityTypes().SelectMany(e=>e.GetProperties()).Where(p=>p.ClrType==typeof(decimal))) { property.SetPrecision(28); property.SetScale(2); }
  m.Entity<PlayerResources>().ToTable(t=>{t.HasCheckConstraint("CK_Credits", "\"Credits\" >= 0");t.HasCheckConstraint("CK_Energy", "\"Energy\" >= 0");});
 }
}
