 public static async Task Seed(GameDb db){foreach(var item in Buildings) if(!await db.BuildingDefinitions.AnyAsync(x=>x.Id==item.Id))db.BuildingDefinitions.Add(item);foreach(var item in Research)if(!await db.ResearchDefinitions.AnyAsync(x=>x.Id==item.Id))db.ResearchDefinitions.Add(item);foreach(var item in Missions)if(!await db.Missions.AnyAsync(x=>x.Id==item.Id))db.Missions.Add(item);foreach(var item in Achievements)if(!await db.Achievements.AnyAsync(x=>x.Id==item.Id))db.Achievements.Add(item);await db.SaveChangesAsync();}
}
